-- Gold layer for the sdp-meta retail demo (decision 9). Hand-written SQL, NOT generated by sdp-meta.
-- Pipeline: sdp_meta_gold_retail (serverless). Publishes to <catalog>.${gold_schema} (pipeline default).
-- Reads the sdp-meta silver tables in <catalog>.${silver_schema}; both schema names come from the
-- pipeline `configuration` set by the bundle, so nothing environment-specific is hard-coded here.

-- ----------------------------------------------------------------------------------------------
-- fact_order_lines: one row per order line. Silver `orders` keeps lines as an array (one row per
-- order, latest revision); this is where the array is split into lines.
CREATE OR REFRESH MATERIALIZED VIEW fact_order_lines
  COMMENT 'One row per order line, from silver orders (batch + streaming channels) joined to products'
  CLUSTER BY (order_date)
AS
WITH lines AS (
  SELECT
    o.order_number,
    o.customer_id,
    o.order_ts,
    o.source_channel,
    l.pos,
    l.line
  FROM ${silver_schema}.orders AS o
  LATERAL VIEW POSEXPLODE(o.order_lines) l AS pos, line
)
SELECT
  lines.order_number,
  lines.pos + 1 AS line_number,
  lines.customer_id,
  lines.order_ts,
  CAST(lines.order_ts AS DATE) AS order_date,
  lines.source_channel,
  lines.line.product_id AS product_id,
  COALESCE(p.product_name, lines.line.product_name) AS product_name,
  p.product_category,
  lines.line.currency AS currency,
  lines.line.price AS unit_price,
  lines.line.qty AS quantity,
  lines.line.price * lines.line.qty AS gross_amount,
  lines.line.promo_id AS promotion_id,
  COALESCE(lines.line.promo_disc, 0) AS promo_discount_pct,
  lines.line.price * lines.line.qty * COALESCE(lines.line.promo_disc, 0) AS discount_amount,
  lines.line.price * lines.line.qty * (1 - COALESCE(lines.line.promo_disc, 0)) AS net_amount
FROM lines
LEFT JOIN ${silver_schema}.products AS p
  ON p.product_id = lines.line.product_id;

-- ----------------------------------------------------------------------------------------------
-- dim_customer_current: the current (open) version of each customer from the SCD2 silver table.
-- Deleted customers have no open version, so they drop out here but stay in the history.
CREATE OR REFRESH MATERIALIZED VIEW dim_customer_current
  COMMENT 'Current version of each customer (SCD2 __END_AT IS NULL) with loyalty segment details'
  CLUSTER BY (customer_id)
AS
SELECT
  c.customer_id,
  c.customer_name,
  c.tax_id,
  c.tax_code,
  c.state,
  c.city,
  c.postcode,
  c.region,
  c.district,
  c.lon,
  c.lat,
  c.ship_to_address,
  c.units_purchased,
  c.loyalty_segment,
  ls.loyalty_segment_description,
  ls.unit_threshold AS loyalty_unit_threshold,
  CAST(FROM_UNIXTIME(c.__START_AT) AS TIMESTAMP) AS current_since
FROM ${silver_schema}.customers AS c
LEFT JOIN ${silver_schema}.loyalty_segments AS ls
  ON ls.loyalty_segment_id = c.loyalty_segment
WHERE c.__END_AT IS NULL;

-- ----------------------------------------------------------------------------------------------
-- customer_history_changes: one row per change event, derived from the SCD2 versions.
--   NEW      first version of a customer
--   CHANGED  a later version (shows before/after for loyalty segment and units purchased)
--   DELETED  the last version was closed and no newer version exists
CREATE OR REFRESH MATERIALIZED VIEW customer_history_changes
  COMMENT 'Customer change events (NEW / CHANGED / DELETED) derived from the SCD2 silver customers table'
  CLUSTER BY (change_date)
AS
WITH versions AS (
  SELECT
    customer_id,
    customer_name,
    city,
    state,
    loyalty_segment,
    units_purchased,
    __START_AT,
    __END_AT,
    ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY __START_AT) AS version_number,
    LAG(loyalty_segment) OVER (PARTITION BY customer_id ORDER BY __START_AT) AS prev_loyalty_segment,
    LAG(units_purchased) OVER (PARTITION BY customer_id ORDER BY __START_AT) AS prev_units_purchased,
    LEAD(__START_AT) OVER (PARTITION BY customer_id ORDER BY __START_AT) AS next_start_at
  FROM ${silver_schema}.customers
),
events AS (
  SELECT
    customer_id,
    customer_name,
    city,
    state,
    version_number,
    CASE WHEN version_number = 1 THEN 'NEW' ELSE 'CHANGED' END AS change_type,
    __START_AT AS changed_at_epoch,
    prev_loyalty_segment,
    loyalty_segment,
    prev_units_purchased,
    units_purchased,
    __END_AT IS NULL AS is_current
  FROM versions
  UNION ALL
  SELECT
    customer_id,
    customer_name,
    city,
    state,
    version_number,
    'DELETED' AS change_type,
    __END_AT AS changed_at_epoch,
    loyalty_segment AS prev_loyalty_segment,
    CAST(NULL AS INT) AS loyalty_segment,
    units_purchased AS prev_units_purchased,
    CAST(NULL AS DOUBLE) AS units_purchased,
    FALSE AS is_current
  FROM versions
  WHERE __END_AT IS NOT NULL
    AND next_start_at IS NULL
)
SELECT
  customer_id,
  customer_name,
  city,
  state,
  version_number,
  change_type,
  CAST(FROM_UNIXTIME(changed_at_epoch) AS TIMESTAMP) AS changed_at,
  CAST(FROM_UNIXTIME(changed_at_epoch) AS DATE) AS change_date,
  prev_loyalty_segment,
  loyalty_segment,
  loyalty_segment - prev_loyalty_segment AS loyalty_segment_change,
  prev_units_purchased,
  units_purchased,
  units_purchased - prev_units_purchased AS units_purchased_change,
  is_current
FROM events;
